-- Other services must access this data through APIs only.
-- No cross-microservice foreign keys are permitted.
-- Owned Tables : {{owned_tables}}
-- Read-Only    : {{readonly_tables}}
-- ============================================================================

CREATE SCHEMA IF NOT EXISTS {{schema_name}};
SET search_path TO {{schema_name}};

