-- ============================================================================
-- MANDATORY: AUDIT TRAIL (NFR)
-- Captures INSERT / UPDATE / DELETE for all owned tables
-- Retention: 7 years
-- ============================================================================

CREATE TABLE {{schema_name}}_audit_log (
    audit_id       BIGSERIAL    PRIMARY KEY,
    table_name     VARCHAR(100) NOT NULL,
    record_id      VARCHAR(100) NOT NULL,
    operation      VARCHAR(20)  NOT NULL,
    old_values     JSONB,
    new_values     JSONB,
    correlation_id UUID,
    performed_by   VARCHAR(100) NOT NULL,
    performed_at   TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT chk_audit_operation CHECK (operation IN ('INSERT', 'UPDATE', 'DELETE'))
);

CREATE INDEX idx_{{schema_name}}_audit_table       ON {{schema_name}}_audit_log(table_name);
CREATE INDEX idx_{{schema_name}}_audit_record      ON {{schema_name}}_audit_log(record_id);
CREATE INDEX idx_{{schema_name}}_audit_correlation ON {{schema_name}}_audit_log(correlation_id);
CREATE INDEX idx_{{schema_name}}_audit_timestamp   ON {{schema_name}}_audit_log(performed_at);

COMMENT ON TABLE {{schema_name}}_audit_log IS 'Audit trail for all owned tables (NFR)';

-- ============================================================================
-- MANDATORY: OUTBOX TABLE (Saga / Event-Driven Architecture NFR)
-- Polling interval: 5 s  |  Retry: exponential backoff, max 3 attempts
-- ============================================================================

CREATE TABLE {{schema_name}}_outbox (
    outbox_id      UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
    aggregate_type VARCHAR(100) NOT NULL,
    aggregate_id   VARCHAR(100) NOT NULL,
    event_type     VARCHAR(100) NOT NULL,
    payload        JSONB        NOT NULL,
    correlation_id UUID         NOT NULL,
    created_at     TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    processed_at   TIMESTAMP,
    status         VARCHAR(20)  NOT NULL DEFAULT 'PENDING',
    retry_count    INTEGER      NOT NULL DEFAULT 0,
    error_message  TEXT,

    CONSTRAINT chk_outbox_status CHECK (status IN ('PENDING', 'PROCESSED', 'FAILED'))
);

CREATE INDEX idx_{{schema_name}}_outbox_pending    ON {{schema_name}}_outbox(status) WHERE status = 'PENDING';
CREATE INDEX idx_{{schema_name}}_outbox_created    ON {{schema_name}}_outbox(created_at);
CREATE INDEX idx_{{schema_name}}_outbox_correlation ON {{schema_name}}_outbox(correlation_id);

COMMENT ON TABLE {{schema_name}}_outbox IS 'Transactional outbox for reliable event publishing (NFR)';

-- ============================================================================
-- TRIGGERS
-- ============================================================================

-- Auto-update updated_at on every UPDATE
CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- CREATE TRIGGER trg_{{table_name}}_updated_at
--     BEFORE UPDATE ON {{table_name}}
--     FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

-- Audit trigger
CREATE OR REPLACE FUNCTION {{schema_name}}_audit_trigger_fn()
RETURNS TRIGGER AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        INSERT INTO {{schema_name}}_audit_log
            (table_name, record_id, operation, new_values, performed_by)
        VALUES
            (TG_TABLE_NAME, NEW.id::TEXT, 'INSERT', row_to_json(NEW), current_user);
    ELSIF TG_OP = 'UPDATE' THEN
        INSERT INTO {{schema_name}}_audit_log
            (table_name, record_id, operation, old_values, new_values, performed_by)
        VALUES
            (TG_TABLE_NAME, NEW.id::TEXT, 'UPDATE', row_to_json(OLD), row_to_json(NEW), current_user);
    ELSIF TG_OP = 'DELETE' THEN
        INSERT INTO {{schema_name}}_audit_log
            (table_name, record_id, operation, old_values, performed_by)
        VALUES
            (TG_TABLE_NAME, OLD.id::TEXT, 'DELETE', row_to_json(OLD), current_user);
    END IF;
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

-- CREATE TRIGGER trg_{{table_name}}_audit
--     AFTER INSERT OR UPDATE OR DELETE ON {{table_name}}
--     FOR EACH ROW EXECUTE FUNCTION {{schema_name}}_audit_trigger_fn();

